/**
 * A NAPI-RS package that ships its WASI build (`<binaryName>.wasi.cjs` beside
 * `<binaryName>.wasm32-wasi.wasm`) loads it through a generated loader that
 * calls each `__napi_register__*` function the WebAssembly module exports
 * before it initializes the module. A function the loader does not call
 * registers nothing, and the export it would have registered is missing.
 *
 * The loader and the module are generated by one build, but a package can
 * publish them from two: nx 22.6 to 23.2 publish a loader that names 53
 * register functions, of which its module exports between 1 and 8 under those
 * names, so every nx command fails on a missing export (`isAiAgent is not a
 * function`) wherever the WASI build runs, Node included. Each name carries a
 * sequence number of the build that generated it, which is what drifted.
 *
 * The repair derives the list from the module the loader loads: it calls the
 * register functions the module exports, in their sequence, and exports what
 * the module registered.
 */

const REGISTER_PREFIX = '__napi_register__';
const REGISTER_CALL = /__napiInstance\.exports\['(__napi_register__[^']+)'\]/gu;
const INITIALIZER = /function __napi_rs_initialize_modules\(__napiInstance\) \{[\s\S]*?\n\}/u;
const REPAIR_MARKER = '// mimic: exports what the module registered';

/** The register functions a loader calls, as written in it. */
export function loaderRegisterCalls(source: string): readonly string[] {
  return [...source.matchAll(REGISTER_CALL)].map((match) => match[1]!);
}

/**
 * The loader with the register calls of `moduleExports`, or `undefined` when
 * it already calls exactly those, or is not a loader of this shape.
 */
export function repairNapiWasiLoader(source: string, moduleExports: readonly string[]): string | undefined {
  if (!INITIALIZER.test(source)) return undefined;
  const registers = moduleExports
    .filter((name) => name.startsWith(REGISTER_PREFIX))
    .sort((left, right) => sequenceOf(left) - sequenceOf(right));
  const listed = new Set(loaderRegisterCalls(source));
  if (registers.length === 0) return undefined;
  if (registers.length === listed.size && registers.every((name) => listed.has(name))) return undefined;
  const initializer = [
    'function __napi_rs_initialize_modules(__napiInstance) {',
    ...registers.map((name) => `  __napiInstance.exports['${name}']?.()`),
    '}'
  ].join('\n');
  const repaired = source.replace(INITIALIZER, () => initializer);
  // The named exports the loader lists are the stale build's; the module's own
  // exports are the ones it registered.
  return repaired.includes(REPAIR_MARKER)
    ? repaired
    : `${repaired.replace(/\n*$/u, '')}\n${REPAIR_MARKER}\nObject.assign(module.exports, __napiModule.exports)\n`;
}

/** The trailing sequence number NAPI-RS gives a register function. */
function sequenceOf(name: string): number {
  const match = /_(\d+)$/u.exec(name);
  return match ? Number(match[1]) : Number.MAX_SAFE_INTEGER;
}

/**
 * The names a WebAssembly binary exports, read from its export section
 * without compiling it.
 */
export function webAssemblyExportNames(bytes: Uint8Array): readonly string[] {
  const reader = { offset: 8 };
  if (
    bytes.byteLength < 8 ||
    bytes[0] !== 0x00 || bytes[1] !== 0x61 || bytes[2] !== 0x73 || bytes[3] !== 0x6d
  ) {
    throw new TypeError('Not a WebAssembly binary.');
  }
  while (reader.offset < bytes.byteLength) {
    const id = bytes[reader.offset++]!;
    const size = readUnsigned(bytes, reader);
    const end = reader.offset + size;
    if (end > bytes.byteLength) throw new TypeError('Truncated WebAssembly section.');
    if (id === 7) {
      const names: string[] = [];
      const count = readUnsigned(bytes, reader);
      const decoder = new TextDecoder();
      for (let index = 0; index < count; index += 1) {
        const length = readUnsigned(bytes, reader);
        names.push(decoder.decode(bytes.subarray(reader.offset, reader.offset + length)));
        reader.offset += length + 1;
        readUnsigned(bytes, reader);
      }
      return names;
    }
    reader.offset = end;
  }
  return [];
}

function readUnsigned(bytes: Uint8Array, reader: { offset: number }): number {
  let result = 0;
  let shift = 0;
  for (;;) {
    if (reader.offset >= bytes.byteLength) throw new TypeError('Truncated WebAssembly integer.');
    const byte = bytes[reader.offset++]!;
    result += (byte & 0x7f) * 2 ** shift;
    if ((byte & 0x80) === 0) return result;
    shift += 7;
    if (shift > 35) throw new TypeError('WebAssembly integer is too long.');
  }
}
